DROP TABLE IF EXISTS "activity_log";
CREATE TABLE "activity_log" ("id" integer primary key autoincrement not null, "log_name" varchar, "description" text not null, "subject_type" varchar, "subject_id" integer, "causer_type" varchar, "causer_id" integer, "properties" text, "created_at" datetime, "updated_at" datetime, "event" varchar, "batch_uuid" varchar);

CREATE INDEX "activity_log_log_name_index" ON "activity_log" ("log_name");

CREATE INDEX "causer" ON "activity_log" ("causer_type", "causer_id");

CREATE INDEX "subject" ON "activity_log" ("subject_type", "subject_id");


DROP TABLE IF EXISTS "bac_members";
CREATE TABLE "bac_members" ("id" integer primary key autoincrement not null, "school_id" integer not null, "employee_id" integer not null, "role" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("school_id") references "schools"("id") on delete cascade, foreign key("employee_id") references "employees"("id") on delete cascade);

CREATE UNIQUE INDEX "bac_members_school_id_role_non_member_unique" ON "bac_members" ("school_id", "role");

CREATE UNIQUE INDEX "bac_members_school_id_employee_id_unique" ON "bac_members" ("school_id", "employee_id");


DROP TABLE IF EXISTS "cache";
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));


DROP TABLE IF EXISTS "cache_locks";
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));


DROP TABLE IF EXISTS "db_config";
CREATE TABLE "db_config" ("id" integer primary key autoincrement not null, "group" varchar not null, "key" varchar not null, "settings" text, "created_at" datetime, "updated_at" datetime);

CREATE UNIQUE INDEX "db_config_group_key_unique" ON "db_config" ("group", "key");


DROP TABLE IF EXISTS "employee_position";
CREATE TABLE "employee_position" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "position_id" integer not null, "appointment_date" date not null, "created_at" datetime, "updated_at" datetime, foreign key("employee_id") references "employees"("id") on delete cascade, foreign key("position_id") references "positions"("id") on delete cascade);


DROP TABLE IF EXISTS "employee_school";
CREATE TABLE "employee_school" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "school_id" integer not null, "assigned_at" date not null, "created_at" datetime, "updated_at" datetime, foreign key("employee_id") references "employees"("id") on delete cascade, foreign key("school_id") references "schools"("id") on delete cascade);


DROP TABLE IF EXISTS "employees";
CREATE TABLE "employees" ("id" integer primary key autoincrement not null, "employee_no" varchar not null, "fname" varchar not null, "mname" varchar not null, "lname" varchar not null, "xname" varchar, "sex" varchar not null, "birthday" varchar not null, "address" varchar not null, "created_at" datetime, "updated_at" datetime, "full_name" varchar not null, "age" varchar);


DROP TABLE IF EXISTS "failed_jobs";
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX "failed_jobs_uuid_unique" ON "failed_jobs" ("uuid");


DROP TABLE IF EXISTS "items";
CREATE TABLE "items" (
  "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
  "name" text NOT NULL,
  "unit" text NOT NULL,
  "created_at" numeric NULL,
  "updated_at" numeric NULL,
  "item_unit_price" numeric NOT NULL DEFAULT '0',
  "school_id" integer NULL,
  "stock_no" text NULL,
  "inventory_item" integer NOT NULL DEFAULT '0',
  "uacs_code_id" integer NULL,
  FOREIGN KEY ("uacs_code_id") REFERENCES "uacs_codes" ("id") ON DELETE SET NULL ON UPDATE NO ACTION,
  FOREIGN KEY ("school_id") REFERENCES "schools" ("id") ON DELETE SET NULL ON UPDATE NO ACTION
);

CREATE UNIQUE INDEX "items_name_unit_unique" ON "items" ("name", "unit");


DROP TABLE IF EXISTS "job_batches";
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));


DROP TABLE IF EXISTS "jobs";
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);

CREATE INDEX "jobs_queue_index" ON "jobs" ("queue");


DROP TABLE IF EXISTS "migrations";
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);


