DROP TABLE IF EXISTS "purchase_item";
CREATE TABLE "purchase_item" ("id" integer primary key autoincrement not null, "purchase_id" integer not null, "item_id" integer, "item_name" varchar not null, "item_unit" varchar not null, "item_quantity" integer not null, "created_at" datetime, "updated_at" datetime, "item_unit_price" numeric not null default '0', foreign key("purchase_id") references "purchases"("id") on delete cascade, foreign key("item_id") references "items"("id") on delete set null);


